import{_ as e,o as t,c as n,a2 as r}from"./chunks/framework.BZO4qERu.js";const m=JSON.parse('{"title":"インテグレーション","description":"","frontmatter":{},"headers":[],"relativePath":"ja/integrations/index.md","filePath":"ja/integrations/index.md","lastUpdated":1792323081000}'),i={name:"ja/integrations/index.md"};function o(s,a,l,h,g,d){return t(),n("div",null,[...a[0]||(a[0]=[r('<h1 id="インテグレーション" tabindex="-1">インテグレーション <a class="header-anchor" href="#インテグレーション" aria-label="Permalink to &quot;インテグレーション&quot;">​</a></h1><p>インテグレーションは Memoh を外部システムにつなぐためのものです。Bot をメッセージプラットフォームに登場させたいとき、またはモデル・メモリ・音声・検索などの上流機能を設定したいときは、ここから始めてください。</p><h2 id="チャネル" tabindex="-1">チャネル <a class="header-anchor" href="#チャネル" aria-label="Permalink to &quot;チャネル&quot;">​</a></h2><p>チャネルを使うと、Memoh クライアントの外からも Bot にアクセスできるようになります。</p><ul><li><strong><a href="/ja/integrations/channels/">チャネル総覧</a></strong>：対応プラットフォームと共通の設定フロー。</li><li><strong><a href="/ja/integrations/channels/slack.html">Slack</a></strong>、<strong><a href="/ja/integrations/channels/telegram.html">Telegram</a></strong>、<strong><a href="/ja/integrations/channels/feishu.html">Feishu</a></strong>、<strong><a href="/ja/integrations/channels/discord.html">Discord</a></strong>、<strong><a href="/ja/integrations/channels/weixin.html">WeChat</a></strong> など。</li></ul><h2 id="プロバイダー" tabindex="-1">プロバイダー <a class="header-anchor" href="#プロバイダー" aria-label="Permalink to &quot;プロバイダー&quot;">​</a></h2><p>プロバイダーは Memoh を外部の機能バックエンドにつなぎます。</p><ul><li><strong><a href="/ja/integrations/providers/llm.html">モデルプロバイダー</a></strong>：上流 API、client type、モデルロールを設定します。</li><li><strong><a href="/ja/integrations/providers/memory/builtin.html">メモリプロバイダー</a></strong>：内蔵メモリ、Mem0、OpenViking から選択します。</li><li><strong><a href="/ja/integrations/providers/web-search.html">ウェブ検索プロバイダー</a></strong>：検索プロバイダーへの接続を設定します。</li></ul><h2 id="プロダクトガイド" tabindex="-1">プロダクトガイド <a class="header-anchor" href="#プロダクトガイド" aria-label="Permalink to &quot;プロダクトガイド&quot;">​</a></h2><p>インテグレーションの設定が終わったら、<strong><a href="/ja/guides/">ガイド</a></strong> で Bot、セッション、メモリ操作、ツール、日常のワークフローを確認してください。</p>',10)])])}const p=e(i,[["render",o]]);export{m as __pageData,p as default};
